import { useState, useCallback, useEffect } from 'react';
import { useIDEStore } from '@/lib/state/ide-store';

// PROBLEMATIC: IDELayout.tsx currently duplicates IDE state
export function IDELayout() {
  // Local state that should come from useIDEStore
  const [activeFile, setActiveFile] = useState<string | null>(null);
  const [openFiles, setOpenFiles] = useState<string[]>([]);
  const [panels, setPanels] = useState<PanelConfig[]>([]);
  const [chatVisible, setChatVisible] = useState(true);
  const [terminalTab, setTerminalTab] = useState('shell');

  // Should use these from useIDEStore instead:
  // const { activeFile, openFiles, panels, chatVisible, terminalTab } = useIDEStore();

  return (
    <div className="ide-layout">
      {/* Component implementation */}
    </div>
  );
}

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { dexieStorage } from 'dexie-storage';

export interface PanelConfig {
  id: string;
  type: 'editor' | 'terminal' | 'preview' | 'chat' | 'file-tree';
  visible: boolean;
  size?: number;
}

export interface IDEState {
  activeFile: string | null;
  openFiles: string[];
  panels: PanelConfig[];
  chatVisible: boolean;
  terminalTab: string;

  // Actions
  setActiveFile: (file: string | null) => void;
  setOpenFiles: (files: string[]) => void;
  addOpenFile: (file: string) => void;
  removeOpenFile: (file: string) => void;
  setPanels: (panels: PanelConfig[]) => void;
  updatePanel: (id: string, updates: Partial<PanelConfig>) => void;
  setChatVisible: (visible: boolean) => void;
  setTerminalTab: (tab: string) => void;
}

export const useIDEStore = create<IDEState>()(
  persist(
    (set) => ({
      activeFile: null,
      openFiles: [],
      panels: [],
      chatVisible: true,
      terminalTab: 'shell',

      setActiveFile: (file) => set({ activeFile: file }),
      setOpenFiles: (files) => set({ openFiles: files }),
      addOpenFile: (file) => set((state) => ({
        openFiles: state.openFiles.includes(file) 
          ? state.openFiles 
          : [...state.openFiles, file]
      })),
      removeOpenFile: (file) => set((state) => ({
        openFiles: state.openFiles.filter((f) => f !== file)
      })),
      setPanels: (panels) => set({ panels }),
      updatePanel: (id, updates) => set((state) => ({
        panels: state.panels.map((p) => 
          p.id === id ? { ...p, ...updates } : p
        )
      })),
      setChatVisible: (visible) => set({ chatVisible: visible }),
      setTerminalTab: (tab) => set({ terminalTab: tab }),
    }),
    {
      name: 'ide-storage',
      storage: createJSONStorage(() => dexieStorage),
    }
  )
);
